/** Read a `CT_Sources`. See `transitional/shared-bibliography.xsd:136`. */
export function readCT_Sources(cur: XmlCursor, ctx: ReadContext): CT_Sources {
  const start = requireStart(cur, 'CT_Sources');
  let SelectedStyle: ST_String | undefined;
  let StyleName: ST_String | undefined;
  let URI: ST_String | undefined;
  let $unknownAttrs: XmlAttr[] | undefined;

  for (const a of start.attrs) {
    if (a.uri === '') {
      switch (a.localName) {
        case 'SelectedStyle': {
          const v = parseST_String(a.value);
          if (v !== undefined) {
            SelectedStyle = v;
            continue;
          }
          ctx.invalidValue('CT_Sources', a, 'ST_String', cur);
          break;
        }
        case 'StyleName': {
          const v = parseST_String(a.value);
          if (v !== undefined) {
            StyleName = v;
            continue;
          }
          ctx.invalidValue('CT_Sources', a, 'ST_String', cur);
          break;
        }
        case 'URI': {
          const v = parseST_String(a.value);
          if (v !== undefined) {
            URI = v;
            continue;
          }
          ctx.invalidValue('CT_Sources', a, 'ST_String', cur);
          break;
        }
      }
    }
    ctx.unexpectedAttribute('CT_Sources', a, cur);
    ($unknownAttrs ??= []).push(a);
  }

  const Source: CT_SourceType[] = [];
  let $unknown: PositionedRaw[] | undefined;
  let $slot = -1;
  let $index: number | undefined;

  const NS_bibliography = ctx.uris['bibliography'];
  cur.next();
  for (;;) {
    const ev = cur.current;
    if (ev === undefined) { ctx.unexpectedEof('CT_Sources', cur); break; }
    if (ev.type === 'endElement') { cur.next(); break; }
    if (ev.type === 'startElement') {
      if (ev.uri === NS_bibliography) {
        switch (ev.localName) {
          case 'Source': {
            Source.push(readCT_SourceType(cur, ctx));
            $slot = 0;
            $index = Source.length - 1;
            continue;
          }
        }
      }
      ctx.unexpectedElement('CT_Sources', ev.localName, ev.uri, cur);
      ($unknown ??= []).push({ afterSlot: $slot, afterIndex: $index, node: cur.skipToRaw() });
      continue;
    }
    if (ev.type === 'text' && !isIgnorableWhitespace(ev.value)) ctx.unexpectedText('CT_Sources', cur);
    cur.next();
  }

  return {
    Source,
    SelectedStyle,
    StyleName,
    URI,
    $unknown,
    $unknownAttrs,
  };
}
